            if (total <= 0)
            {
                return null;
            }
            else
            {
                var h = total / 3600;
                var m = (total % 3600) / 60;
                if (h > 0)
                {
                    var mM = m.ToString("00");
                    return $"{(h)}:{(mM)}";
                }
                else
                {
                    return $"{(m)}m";
                }
            }
        }
    }

