    public static IReadOnlyList<double> Smooth(IReadOnlyList<double> z, int i, int n)
    {
        if (i >= n)
        {
            return new List<double> {  };
        }
        else
        {
            var lo = Math.Max(0, i - 1);
            var hi = Math.Min(n - 1, i + 1);
            var sum = SumFrom(z, lo, hi, 0.0);
            var a = sum / (double)((hi - lo) + 1);
            var i1 = i + 1;
            var rest = Smooth(z, i1, n);
            return Cons(a, rest);
        }
    }

    public static double SumFrom(IReadOnlyList<double> z, int i, int hi, double acc)
    {
        if (i > hi)
        {
            return acc;
        }
        else
        {
            var v = z[i];
            var acc1 = acc + v;
            var i1 = i + 1;
            return SumFrom(z, i1, hi, acc1);
        }
    }

    public static string WaveFrame(int step)
    {
        var p = step % 18;
        int i;
        if (p < 10)
        {
            i = p;
        }
        else
        {
            i = 18 - p;
        }
        return WaveCells(i, 0);
    }

    public static string WaveCells(int i, int j)
    {
        if (j >= 10)
        {
            return "";
        }
        else
        {
            var l = Math.Max(0, 7 - Math.Abs(i - j));
            var c = Bar(l);
            var j1 = j + 1;
            var r = WaveCells(i, j1);
            return c + r;
        }
    }

    public static string ErrorFrame(int f, string msg, int width)
    {
        var cycle = 18 + MarqueeFrames;
        if (f >= (ErrorCycles * cycle))
        {
            return null;
        }
        else
        {
            var p = f % cycle;
            if (p < 18)
            {
                return WaveFrame(p);
            }
            else
            {
                var pad = string.Concat(Enumerable.Repeat(" ", width));
                var a = pad + msg;
                var all = a + "    ";
                var len = all.Length;
                var start = (int)((double)(p - 18) * MarqueeSpeed) % len;
                return Window(all, start, width, len);
            }
        }
    }

    public static string Window(string s, int start, int n, int len)
    {
        if (n <= 0)
        {
            return "";
        }
        else
        {
            var i = start % len;
            var c = s[i].ToString();
            var next = start + 1;
            var n1 = n - 1;
            var rest = Window(s, next, n1, len);
            return c + rest;
        }
    }

