    public static bool Rollover(double? lastU, double u, string lastR, string r, DateTime now)
    {
        var d = Format.ParseISO(r);
        if (lastU == null)
        {
            return false;
        }
         else if (lastU.Value < 0.0)
        {
            return false;
        }
         else if (d == null)
        {
            return false;
        }
         else if (d.Value <= now)
        {
            return false;
        }
         else if ((lastR != null) && (lastR != r))
        {
            return true;
        }
         else if (lastU.Value > (u + BigDrop))
        {
            return true;
        }
        else
        {
            return false;
        }
    }

