            return Click.Fetch;
        }
    }

    public static double BackoffSecs(int count, double? retry)
    {
        var e = Math.Min(BackoffBase * Math.Pow(2.0, (double)(count - 1)), BackoffCap);
        if (retry == null)
        {
            return e;
        }
        else
        {
            return Math.Max(retry.Value, e);
        }
    }

