    public static string StatusLine(AppError e, DateTime? last, DateTime? until, DateTime? next, DateTime now)
    {
        string prefix;
        if (e == null)
        {
            prefix = "";
        }
         else if (e.Kind == AppErrorKind.RateLimited)
        {
            prefix = "rate-limited · ";
        }
        else
        {
            var sym = ErrorSymbol(e);
            prefix = $"{(sym)} · ";
        }
        string seen;
        if (last == null)
        {
            seen = "never";
        }
        else
        {
            seen = RelativeTime(last.Value, now);
        }
        string tail;
        if ((e != null) && (e.Kind == AppErrorKind.RateLimited && (until != null)))
        {
            var w = Math.Max(0, (int)(until.Value - now).TotalSeconds);
            var a = NextAttempt(w);
            tail = $"next in {(a)}";
        }
         else if (last == null)
        {
            tail = "click to refresh";
        }
         else if (next != null)
        {
            var w = Math.Max(0, (int)(next.Value - now).TotalSeconds);
            if (w <= 0)
            {
                tail = "next now…";
            }
             else if (w < 60)
            {
                tail = $"next in {(w)}s";
            }
            else
            {
                var m = w / 60;
                var r = w % 60;
                tail = $"next in {(m)}m {(r)}s";
            }
        }
        else
        {
            tail = "—";
        }
        return $"{(prefix)}Last updated: {(seen)} · {(tail)}";
    }

