        }
        IReadOnlyList<Row> body;
        if (r == null)
        {
            body = new List<Row> {  };
        }
        else
        {
            IReadOnlyList<Row> reset;
            if (r.FiveHour == null)
            {
                reset = new List<Row> {  };
            }
            else
            {
                reset = new List<Row> { Row.Reset() };
            }
            var w = WeeklyRows(r);
            IReadOnlyList<Row> weekly;
            if (w.Count == 0)
            {
